import{_ as a,o,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Jewel -- Passive Monitors","description":"","frontmatter":{"title":"CDS Jewel -- Passive Monitors","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","Distributed Storage","Quorum","Passive Monitor","Brain Split"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Passive_Monitors.md","filePath":"posts/2015/CDS_Jewel_--_Passive_Monitors.md","lastUpdated":1780459816000}'),i={name:"posts/2015/CDS_Jewel_--_Passive_Monitors.md"};function l(s,t,n,u,d,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>讨论Ceph集群中被动监控器的应用，包括其设计理念、潜在问题和解决方案。</p><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>被动监控器</strong>：一种不参与Quorum的监控器，不确认或接受提案，但会接收到所有提案。</li><li><strong>目的</strong>：增强集群的可用性和灾难恢复能力。</li><li><strong>设计理念</strong>：在Quorum中至少有一个被动监控器，以便在需要时可以快速将其转换为活跃监控器，参与Quorum。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>如何将被动监控器转换为活跃监控器</strong>：需要设计一种机制来安全地将被动监控器加入到活跃监控器集合中。</li><li><strong>如何避免脑裂问题</strong>：当集群分布在多个房间时，如何防止不同房间中的监控器同时认为自己是Quorum的一部分。</li><li><strong>被动监控器的更新</strong>：如何确保被动监控器与Quorum的状态保持同步，同时避免过度负载活跃监控器。</li><li><strong>被动监控器的角色</strong>：被动监控器是否应该参与选举，以及是否应该处理客户端请求。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>初步方案</strong>：将被动监控器作为Quorum的备份，由管理员手动将其提升为活跃监控器。</li><li><strong>长期方案</strong>：研究如何自动将被动监控器提升为活跃监控器，同时避免脑裂问题。</li><li><strong>被动监控器的更新</strong>：将被动监控器与一个活跃监控器绑定，以便接收更新。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>设计和实现被动监控器的初步方案。</li><li>研究和解决脑裂问题。</li><li>评估被动监控器参与选举和处理客户端请求的可行性。</li><li>撰写相关文档和代码注释。</li></ul><h4 id="关键术语" tabindex="-1">关键术语 <a class="header-anchor" href="#关键术语" aria-label="Permalink to &quot;关键术语&quot;">​</a></h4><ul><li><strong>被动监控器</strong>：Passive Monitor</li><li><strong>Quorum</strong>：Quorum</li><li><strong>脑裂</strong>：Split Brain</li><li><strong>活跃监控器</strong>：Active Monitor</li><li><strong>客户端请求</strong>：Client Requests</li></ul>',13)])])}const c=a(i,[["render",l]]);export{g as __pageData,c as default};
